  background: var(--bg);
  color: var(--ink);
  font: 400 1.0625rem/1.6 var(--body);
  font-synthesis: none;
  -webkit-text-size-adjust: 100%;
}

::selection { background: var(--accent); color: var(--surface); }

h1, h2, h3 {
  font-family: var(--display);
  font-weight: 400;
  text-wrap: balance;
  margin: 0;
}
h1 { font-size: clamp(2.5rem, 1.6rem + 4.4vw, 4.75rem); line-height: 1.04; letter-spacing: -0.015em; }
h2 { font-size: clamp(1.9rem, 1.5rem + 1.8vw, 2.55rem); line-height: 1.1; letter-spacing: -0.01em; }
h3 { font-size: 1.42rem; line-height: 1.2; }
p { margin: 0; text-wrap: pretty; }

a { color: var(--accent); text-underline-offset: 0.2em; text-decoration-thickness: 1px; }
a:hover { text-decoration-thickness: 2px; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: 2px; }

img { display: block; max-width: 100%; height: auto; }

.wrap { width: min(100% - 2 * clamp(1rem, 4vw, 2.5rem), 72rem); margin-inline: auto; }

.skip {
  position: absolute; left: var(--s2); top: -10rem;
  background: var(--surface); padding: var(--s1) var(--s2);
}
.skip:focus { top: var(--s2); }

/* ---- the signature: a glaze test tile ----
   An upright slab dipped two-thirds in glaze at a slight hand angle,
   glaze pooling darker at the dip line, raw clay foot, hanging hole. */
.tile {
  --g: var(--ash);
  --w: 0.8rem;
  display: inline-block;
  flex: none;
  inline-size: var(--w);
  aspect-ratio: 2 / 3;
  border-radius: 0.18em 0.18em 0.1em 0.1em;
  -webkit-mask: radial-gradient(circle at 50% 14%, transparent 0 9%, #000 10.5%);
          mask: radial-gradient(circle at 50% 14%, transparent 0 9%, #000 10.5%);
  background:
    linear-gradient(174deg,
      var(--g) 0 57%,
      color-mix(in oklch, var(--g), black 22%) 57% 65%,
      var(--clay) 65.6%);
  box-shadow: inset 0 0 0 1px oklch(0.23 0.02 262 / 0.14);
}
.tile-sm { --w: 0.75rem; }
.tile-md { --w: 2.25rem; }
.tile-lg { --w: 2.75rem; }
.g-celadon { --g: var(--celadon); }
.g-tenmoku { --g: var(--tenmoku); }
.g-shino { --g: var(--shino); }
.g-cobalt { --g: var(--cobalt); }
.g-ash { --g: var(--ash); }

/* ---- buttons ---- */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  min-height: 2.9rem; padding: 0.6rem 1.35rem;
  background: var(--accent); color: var(--surface);
  font-weight: 700; text-decoration: none;
  border-radius: 0.35rem;
  touch-action: manipulation;
  transition: background-color 150ms ease-out;
}
@media (hover: hover) { .btn:hover { background: var(--accent-press); } }
.btn:active { background: var(--accent-press); }
.btn-small { min-height: 2.75rem; padding-inline: 1rem; }

/* ---- header ---- */
.site-header {
  display: flex; flex-wrap: wrap; align-items: center; gap: var(--s2) var(--s4);
  padding-block: var(--s3);
}
.wordmark {
  display: inline-flex; align-items: center; gap: 0.55rem;
  font: 400 1.5rem/1 var(--display); color: var(--ink); text-decoration: none;
}
.wordmark .tile { --w: 0.95rem; --g: var(--cobalt); }
.site-header nav { margin-inline-start: auto; }
.site-header nav ul, .site-footer nav ul {
  display: flex; flex-wrap: wrap; gap: 0.25rem 1.5rem; list-style: none; margin: 0; padding: 0;
}
.site-header nav a {
  display: inline-block; padding-block: 0.6rem; color: var(--ink); text-decoration: none;
}
.site-header nav a:hover { text-decoration: underline; }
@media (max-width: 40rem) {
  .site-header nav { order: 3; flex-basis: 100%; margin: 0; }
  .site-header .btn { margin-inline-start: auto; }
}

/* ---- hero ---- */
.hero {
  display: grid; gap: var(--s4); align-items: center;
  padding-block: var(--s4) var(--s6);
}
.hero-copy { display: grid; gap: var(--s3); justify-items: start; }
.lede { font-size: 1.2rem; max-width: 34ch; color: var(--muted); }
.actions { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s2) var(--s3); padding-top: var(--s1); }
.link-quiet { padding-block: 0.6rem; font-weight: 700; }

.hero-figure { margin: 0; }
.hero-figure img, .piece img, .story-figure img {
  width: 100%; object-fit: cover;
  background: var(--clay);           /* holds the space until the photo lands */
  color: var(--ink); font-style: italic;
}
.hero-figure img { aspect-ratio: 4 / 5; border-radius: 0.5rem; }

.glaze-row {
  display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between;
  gap: var(--s2); margin-top: calc(-1 * var(--s4));
  padding-inline: var(--s3);
  position: relative;
}
.glaze-row p { flex-basis: 100%; color: var(--muted); font-size: 0.95rem; }
.tiles {
  display: flex; flex-wrap: wrap; gap: var(--s2);
  list-style: none; margin: 0; padding: 0;
}
.tiles li {
  display: grid; justify-items: center; gap: 0.35rem;
  font-size: 0.85rem; color: var(--muted);
}

@media (min-width: 56rem) {
  .hero { grid-template-columns: 1.1fr 0.9fr; gap: var(--s5); }
}

/* ---- shared section bits ---- */
.band { background: var(--surface); padding-block: var(--s6); }
.section-head { display: grid; gap: var(--s2); max-width: 40rem; margin-bottom: var(--s4); }
.section-head p { color: var(--muted); }

/* ---- classes ---- */
.class-list { border-top: 1px solid var(--rule); }
.class {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: var(--s2) var(--s3);
  padding-block: var(--s4);
  border-bottom: 1px solid var(--rule);
}
.class > .tile { grid-row: span 3; }
.class-body { display: grid; gap: var(--s1); max-width: 34rem; }
.facts { display: flex; flex-wrap: wrap; gap: var(--s1) var(--s4); margin: 0; }
.facts div { display: grid; }
.facts dt { font-size: 0.9rem; color: var(--muted); }
.facts dd { margin: 0; font-weight: 700; font-size: 1.2rem; font-variant-numeric: tabular-nums; }
.class .btn { justify-self: start; }

@media (min-width: 56rem) {
  .class {
    grid-template-columns: auto minmax(0, 1fr) 15rem 13rem;
    align-items: center;
  }
  .class > .tile { grid-row: auto; }
  .class .btn { justify-self: end; }
}
.booking-note { margin-top: var(--s4); max-width: 44rem; }

/* ---- shop ---- */
.shop { padding-block: var(--s6); }
.pieces {
  display: grid; gap: var(--s4) var(--s3);
  grid-template-columns: repeat(auto-fit, minmax(13rem, 1fr));
  list-style: none; margin: 0; padding: 0;
}
.piece { display: grid; gap: 0.3rem; align-content: start; }
.piece img { aspect-ratio: 4 / 5; border-radius: 0.3rem; margin-bottom: var(--s1); }
.piece h3 { font-size: 1.25rem; }
.glaze { display: flex; align-items: center; gap: 0.5rem; color: var(--muted); }
.price { font-weight: 700; font-variant-numeric: tabular-nums; }
/* staggered like pots on a shelf, only where four fit in a row */
@media (min-width: 64rem) {
  .pieces { grid-template-columns: repeat(4, 1fr); }
  .piece:nth-child(even) { margin-top: var(--s5); }
}

/* ---- story ---- */
.story-grid { display: grid; gap: var(--s4); align-items: center; }
.story-copy { display: grid; gap: var(--s2); max-width: 36rem; }
.story-copy h2 { margin-bottom: var(--s1); }
.story-figure { margin: 0; }
.story-figure img { aspect-ratio: 4 / 3; border-radius: 0.5rem; }
@media (min-width: 56rem) {
  .story-grid { grid-template-columns: 1fr 1.15fr; gap: var(--s5); }
}

/* ---- visit ---- */
.visit { padding-block: var(--s6); }
.visit h2 { margin-bottom: var(--s4); }
.visit h3 { margin-bottom: var(--s2); }
.visit-grid { display: grid; gap: var(--s4); grid-template-columns: repeat(auto-fit, minmax(min(100%, 20rem), 1fr)); }
.hours { margin: 0; }
.hours div { padding-block: 0.75rem; border-bottom: 1px solid var(--rule); }
.hours div:first-child { border-top: 1px solid var(--rule); }
.hours dt { font-weight: 700; }
.hours dd { margin: 0; color: var(--muted); font-variant-numeric: tabular-nums; }
address { font-style: normal; margin-bottom: var(--s2); }
.visit a { display: inline-block; padding-block: 0.4rem; }

/* ---- footer ---- */
.site-footer { background: var(--ink); color: var(--bg); padding-block: var(--s5); }
.footer-inner { display: grid; gap: var(--s2); }
.site-footer .wordmark { color: var(--bg); }
.site-footer a { color: var(--bg); display: inline-block; padding-block: 0.4rem; }
.site-footer :focus-visible { outline-color: var(--bg); }
.small { font-size: 0.9rem; color: oklch(0.8 0.01 262); }
